const api = game.modules.get('la-talents')?.api;
if (!api?.restLeader) return ui.notifications.warn('la-talents: restLeader is not available. Is Lancer Automations enabled and the world fully loaded?');
if (!game.user.isGM) return ui.notifications.warn('Run this as the GM.');
const tokens = canvas.tokens.controlled;
if (!tokens.length) return ui.notifications.warn('Select the resting mech token(s) first.');
for (const t of tokens) await api.restLeader(t.actor);
